import{_ as o,C as e,o as l,c as s,a2 as t,E as i}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Memory & Familiarity","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/memory-and-familiarity.md","filePath":"en/guide/magic/memory-and-familiarity.md"}'),d={name:"en/guide/magic/memory-and-familiarity.md"};function c(m,a,p,h,u,y){const r=e("WikiVisual"),n=e("WikiBadges");return l(),s("div",null,[a[0]||(a[0]=t('<h1 id="memory-familiarity" tabindex="-1">Memory &amp; Familiarity <a class="header-anchor" href="#memory-familiarity" aria-label="Permalink to &quot;Memory &amp; Familiarity&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Availability not established.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Knowing a spell permanently differs from preparing it in <a href="/Syrolands-Public/en/guide/glossary.html#active-memory">Active Memory</a>.</li><li><a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> improves fluency with a <a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Core Pattern</a> without spending extra skillcap.</li><li>Preparation removes extra reference time, not normal casting costs or risks.</li></ul><p><span id="spell-memory-and-familiarity"></span><span id="at-a-glance"></span><span id="trade-offs"></span></p>',5)),i(r,{"asset-id":"spot-active-memory"}),i(n,{ids:"icon-active-memory"}),a[1]||(a[1]=t('<h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Player meaning</th></tr></thead><tbody><tr><td>Known</td><td>The pattern is learned permanently.</td></tr><tr><td>Prepared</td><td>Begin the normal casting sequence without extra lookup.</td></tr><tr><td>Known but unprepared</td><td>Consult or recall the pattern before normal casting; this creates exposure.</td></tr><tr><td>Learned / Practiced / Mastered</td><td>Shared fluency tiers; exact spell effects and timing remain open.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>A spellbook offers access to its spells, with normal casting requirements.</td><td>Permanent knowledge can exceed the set prepared for immediate access to normal casting.</td></tr><tr><td>Magery measures general casting skill.</td><td>Familiarity additionally distinguishes practice with each pattern.</td></tr></tbody></table><p>UO rules vary by era and shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/magery/" target="_blank" rel="noreferrer">Official UO: Magery and Meditation</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>While being chased, you may know Remove Curse but need to consult your book because it was not prepared. Finding the pattern still leaves the normal cast to complete.</p><h2 id="progression-trade-offs" tabindex="-1">Progression / trade-offs <a class="header-anchor" href="#progression-trade-offs" aria-label="Permalink to &quot;Progression / trade-offs&quot;">​</a></h2><p>INT may support capacity and complexity; Meditation may help rearrange preparation. Variants may need extra preparation. Capacity, delays, switching and costs remain open, and martial <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">SA</a> slots do not define spell memory. Calendar absence should not punish fluency.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/familiarity.html">Shared Familiarity</a> · <a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Books and scrolls</a> · <a href="/Syrolands-Public/en/guide/magic/meditation-and-concentration.html">Meditation</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p>Read the <a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html">Memory &amp; Familiarity</a> design specification.</p><p><span id="shared-practice-states"></span></p>',14))])}const b=o(d,[["render",c]]);export{g as __pageData,b as default};
